import React, { useEffect, useState, useRef } from "react";
import { useLocation, useNavigate } from "react-router-dom";
import { useReactToPrint } from "react-to-print";
import {
  Smile,
  Leaf,
  HeartPulse,
  Wind,
  Thermometer,
  Brain,
  Zap,
} from "lucide-react";

const iconMap = {
  fever: <Thermometer className="inline w-5 h-5 text-red-500" />,
  cough: <Wind className="inline w-5 h-5 text-blue-500" />,
  headache: <Brain className="inline w-5 h-5 text-purple-500" />,
  fatigue: <Zap className="inline w-5 h-5 text-yellow-500" />,
  chest_pain: <HeartPulse className="inline w-5 h-5 text-pink-500" />,
};

export default function SuggestionPage() {
  const location = useLocation();
  const navigate = useNavigate();
  const [lang, setLang] = useState("english");
  const [showLangPopup, setShowLangPopup] = useState(false);
  const [suggestions, setSuggestions] = useState([]);
  const printRef = useRef();

  const { predictions = [], symptoms = [] } = location.state || {};

  // 🧠 fetch suggestions from backend
  useEffect(() => {
    if (symptoms.length > 0) {
      fetch("http://127.0.0.1:5000/api/suggestions", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ symptoms, lang }),
      })
        .then((res) => res.json())
        .then((data) => setSuggestions(data.suggestions || []))
        .catch(() => setSuggestions([]));
    }
  }, [symptoms, lang]);

  const handlePrint = useReactToPrint({
    content: () => printRef.current,
    documentTitle: `Health_Suggestions_Report_${new Date().toISOString()}`,
  });

  return (
    <div className="p-8 font-sans text-gray-800 bg-white min-h-screen">
      {/* 🌍 Language popup toggle */}
      <div className="flex justify-between items-center mb-4">
        <button
          onClick={() => navigate(-1)}
          className="px-3 py-1 border rounded-md hover:bg-gray-100"
        >
          ← Back
        </button>
        <div>
          <button
            onClick={() => setShowLangPopup(true)}
            className="px-3 py-1 bg-gray-200 rounded-md"
          >
            {lang === "english" ? "English" : "Kriol"}
          </button>
        </div>
      </div>

      {/* 🌐 Popup */}
      {showLangPopup && (
        <div className="fixed inset-0 flex items-center justify-center bg-black/30 z-50">
          <div className="bg-white p-6 rounded-xl shadow-lg text-center">
            <h3 className="font-semibold mb-3">Choose Language</h3>
            <div className="flex gap-3 justify-center">
              <button
                className={`px-4 py-2 rounded-lg ${
                  lang === "english" ? "bg-blue-500 text-white" : "bg-gray-200"
                }`}
                onClick={() => {
                  setLang("english");
                  setShowLangPopup(false);
                }}
              >
                English
              </button>
              <button
                className={`px-4 py-2 rounded-lg ${
                  lang === "kriol" ? "bg-blue-500 text-white" : "bg-gray-200"
                }`}
                onClick={() => {
                  setLang("kriol");
                  setShowLangPopup(false);
                }}
              >
                Kriol
              </button>
            </div>
          </div>
        </div>
      )}

      <div ref={printRef}>
        <h1 className="text-3xl font-bold mb-6">💡 Health Suggestions</h1>

        {/* 🩺 Possible conditions */}
        <section className="mb-6">
          <h2 className="text-xl font-semibold flex items-center gap-2">
            <HeartPulse /> Possible Conditions
          </h2>
          {predictions.length > 0 ? (
            <ul className="list-disc ml-6">
              {predictions.map((p, i) => (
                <li key={i}>
                  {p.disease} ({(p.score * 100).toFixed(1)}%)
                </li>
              ))}
            </ul>
          ) : (
            <p>No disease prediction available.</p>
          )}
        </section>

        {/* 😊 Symptoms you mentioned */}
        <section className="mb-6">
          <h2 className="text-xl font-semibold flex items-center gap-2">
            <Smile /> Symptoms You Mentioned
          </h2>
          {symptoms.length > 0 ? (
            <ul className="list-disc ml-6">
              {symptoms.map((s, i) => (
                <li key={i}>
                  {iconMap[s] || "•"} {s}
                </li>
              ))}
            </ul>
          ) : (
            <p>No symptoms found.</p>
          )}
        </section>

        {/* 🌿 Suggestions from dataset */}
        <section>
          <h2 className="text-xl font-semibold flex items-center gap-2">
            <Leaf /> What You Can Do Now
          </h2>
          {suggestions.length > 0 ? (
            <ul className="list-disc ml-6">
              {suggestions.map((item, i) => (
                <li key={i}>
                  <strong>{item.symptom}:</strong> {item.suggestion}
                </li>
              ))}
            </ul>
          ) : (
            <p>
              Rest well, stay hydrated, and monitor your symptoms. If your
              condition worsens or new symptoms appear, please visit the nearest
              clinic or hospital.
            </p>
          )}
        </section>
      </div>

      <div className="flex justify-end mt-8">
        <button
          onClick={handlePrint}
          className="px-4 py-2 bg-blue-500 text-white rounded-md hover:bg-blue-600"
        >
          Save as PDF
        </button>
      </div>
    </div>
  );
}
